"""Generated by Cascade from a 3-qubit circuit."""
from guppylang import guppy
from guppylang.std.quantum import qubit, measure, discard, h, rz, s, t, angle
from guppylang.std.builtins import result


@guppy
def main() -> None:
    q0 = qubit(); q1 = qubit(); q2 = qubit()
    h(q0)  # h0
    h(q1)  # h1
    h(q2)  # h2
    s(q0)  # p0
    t(q1)  # p1
